{
  "status": "NEEDS_IMPROVEMENT",
  "core_findings": [
    "Training separation is weakest in Electronics: negatives outrank positives at 10.72% of positions, and the 10th-percentile margin is -0.0838. Industrial_and_Scientific also has weaker separation than Movies_and_TV and CDs_and_Vinyl.",
    "Embedding alignment scores range from 0.5344 to 0.5781; these do not establish representation collapse. Gradient health is unassessed because no gradients were retained."
  ],
  "key_implications": [
    "The model separates sampled training positives and negatives most reliably in Movies_and_TV and least reliably in Electronics.",
    "These training diagnostics cannot establish validation ranking quality or recommendation diversity."
  ],
  "evidence": {
    "headline_metrics": {
      "Electronics:pos_neg_neg_beats_pos_rate": 0.1072,
      "Electronics:pos_neg_margin_p10": -0.0838,
      "Industrial_and_Scientific:pos_neg_neg_beats_pos_rate": 0.0627,
      "CDs_and_Vinyl:pos_neg_neg_beats_pos_rate": 0.0344,
      "Movies_and_TV:pos_neg_neg_beats_pos_rate": 0.0137
    },
    "brief_metric_read": {
      "pos_neg_neg_beats_pos_rate": "Training ranking errors vary substantially across datasets.",
      "embedding_collapse_score": "Measures directional alignment, not definitive collapse.",
      "existing_gradients_finite": "Null across datasets; gradient finiteness is unknown."
    }
  }
}
